//! The codec against the reference decoder's own answers.
//!
//! `shiso/test-vectors/loader/ple-codec-vectors.json` is generated by
//! `shiso/scripts/ple_codec_vectors.sh`, which compiles the reference decoder
//! and runs it over these exact inputs. Nothing here approximates: the row
//! identifiers are compared as integers and the decoded weights as their bit
//! patterns, because a codec that is right to within an ulp is a codec that
//! disagrees with the device kernel.

use std::sync::Arc;

use shiso_core::ids::TokenId;
use shiso_ple::codec::{self, TRELLIS_HEAD_DIM};
use shiso_ple::{PleError, PleParams, PleParamsDesc, PleRowType};

/// The committed vectors, as generated.
fn vectors() -> serde_json::Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../test-vectors/loader/ple-codec-vectors.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|err| {
        panic!("{path} is committed and must be readable; regenerate it with shiso/scripts/ple_codec_vectors.sh: {err}")
    });
    serde_json::from_str(&text).expect("the vectors are JSON")
}

fn u32of(value: &serde_json::Value) -> u32 {
    u32::try_from(value.as_u64().expect("an unsigned integer")).expect("it fits a u32")
}

fn u64s(value: &serde_json::Value) -> Vec<u64> {
    value
        .as_array()
        .expect("an array")
        .iter()
        .map(|v| v.as_u64().expect("an unsigned integer"))
        .collect()
}

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len() / 2)
        .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).expect("two hex digits"))
        .collect()
}

fn halves(hex: &str) -> Vec<u16> {
    bytes(hex)
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u16::from_le_bytes(*pair))
        .collect()
}

/// Rebuilds the parameters the vectors were generated with.
fn params(v: &serde_json::Value, row_type: PleRowType, head_dim: u32, biased: bool) -> PleParams {
    let ngram = u32of(&v["ngram_size"]);
    let bias = biased.then(|| Arc::new(halves(v["head_bias"].as_str().expect("hex"))));
    PleParams::new(PleParamsDesc {
        row_type,
        ngram_size: ngram,
        heads_per_ngram: u32of(&v["heads_per_ngram"]),
        head_dim,
        eos_token: TokenId::new(u32of(&v["eos_token"])),
        // The reference carries four multiplier slots whatever the gram width;
        // only the first `ngram_size` of them are ever read, and this crate
        // refuses a table that supplies a different number rather than
        // silently reading past the width it was told.
        multipliers: u64s(&v["multipliers"])[..ngram as usize].to_vec(),
        head_offsets: u64s(&v["head_offsets"]),
        head_vocab: u64s(&v["head_vocab"]),
        head_bias: bias,
    })
    .expect("the reference parameters are valid")
}

#[test]
fn every_row_identifier_matches_the_reference_hash() {
    let v = vectors();
    let p = params(&v, PleRowType::TrellisK6, TRELLIS_HEAD_DIM, true);
    let tokens: Vec<TokenId> = v["tokens"]
        .as_array()
        .expect("an array")
        .iter()
        .map(|t| TokenId::new(u32of(t)))
        .collect();

    let cases = v["row_ids"].as_array().expect("cases");
    assert!(cases.len() >= 5, "the window rules need every case");
    for case in cases {
        let name = case["name"].as_str().expect("a name");
        let pos0 = u32of(&case["pos0"]);
        let n = u32of(&case["n"]);
        let want = u64s(&case["rows"]);
        let mut got = vec![0u64; want.len()];
        codec::row_ids(&p, &tokens, pos0, n, &mut got).expect("the buffer is exact");
        assert_eq!(got, want, "case {name}");
    }
}

#[test]
fn both_row_codecs_decode_bit_for_bit_against_the_reference() {
    let v = vectors();
    for case in v["dequant"].as_array().expect("cases") {
        let name = case["name"].as_str().expect("a name");
        let head_dim = u32of(&case["head_dim"]);
        let row_type = match case["row_type"].as_u64().expect("a codec") {
            1 => PleRowType::TrellisK6,
            _ => PleRowType::BlockNl4,
        };
        let biased = case["biased"].as_bool().expect("a flag");
        let p = params(&v, row_type, head_dim, biased);

        let src = bytes(case["src"].as_str().expect("hex"));
        assert_eq!(
            src.len() as u64,
            case["row_bytes"].as_u64().expect("a stride"),
            "case {name} row stride"
        );
        assert_eq!(p.row_bytes() as usize, src.len(), "case {name} row_bytes");

        let head = u32of(&case["head"]);
        let mut got = vec![0f32; head_dim as usize];
        codec::dequant_row(&p, &src, head, &mut got).expect("the buffers are exact");

        let want = u64s(&case["weights"]);
        assert_eq!(got.len(), want.len(), "case {name} weight count");
        for (i, (g, w)) in got.iter().zip(&want).enumerate() {
            assert_eq!(
                u64::from(g.to_bits()),
                *w,
                "case {name} weight {i}: {g} is not the reference bit pattern"
            );
        }
    }
}

#[test]
fn the_two_codecs_have_the_row_strides_their_checkpoints_ship() {
    let v = vectors();
    // The block codec at the shipped row width: thirty-two weights per
    // eighteen-byte block, five blocks.
    assert_eq!(
        params(&v, PleRowType::BlockNl4, TRELLIS_HEAD_DIM, false).row_bytes(),
        90
    );
    // The trellis codec: a half-precision row scale then six bits a weight.
    assert_eq!(
        params(&v, PleRowType::TrellisK6, TRELLIS_HEAD_DIM, true).row_bytes(),
        122
    );
}

#[test]
fn a_gather_that_reaches_past_the_history_is_refused_rather_than_hashing_absent_tokens() {
    let v = vectors();
    let p = params(&v, PleRowType::BlockNl4, 64, false);
    let tokens = vec![TokenId::new(5); 4];
    let mut out = vec![0u64; 4 * p.n_heads() as usize];
    let err = codec::row_ids(&p, &tokens, 2, 4, &mut out).expect_err("only four tokens exist");
    assert!(
        matches!(
            err,
            PleError::BufferTooSmall {
                what: "token history",
                ..
            }
        ),
        "{err:?}"
    );
}

#[test]
fn a_short_identifier_buffer_is_refused_rather_than_truncated() {
    let v = vectors();
    let p = params(&v, PleRowType::BlockNl4, 64, false);
    let tokens = vec![TokenId::new(5); 8];
    let mut out = vec![0u64; p.n_heads() as usize];
    let err = codec::row_ids(&p, &tokens, 0, 2, &mut out).expect_err("two positions need two sets");
    assert!(
        matches!(
            err,
            PleError::BufferTooSmall {
                what: "row identifier output",
                ..
            }
        ),
        "{err:?}"
    );
}

#[test]
fn a_short_row_or_a_short_destination_is_refused_rather_than_read_past() {
    let v = vectors();
    let p = params(&v, PleRowType::TrellisK6, TRELLIS_HEAD_DIM, true);
    let src = vec![0u8; 121];
    let mut dst = vec![0f32; 160];
    let err = codec::dequant_row(&p, &src, 0, &mut dst).expect_err("one byte short of a row");
    assert!(
        matches!(
            err,
            PleError::BufferTooSmall {
                what: "quantized row",
                ..
            }
        ),
        "{err:?}"
    );

    let src = vec![0u8; 122];
    let mut dst = vec![0f32; 159];
    let err = codec::dequant_row(&p, &src, 0, &mut dst).expect_err("one weight short");
    assert!(
        matches!(
            err,
            PleError::BufferTooSmall {
                what: "decoded row",
                ..
            }
        ),
        "{err:?}"
    );
}

#[test]
fn the_head_bias_is_read_at_the_head_the_row_belongs_to() {
    // The same bytes decoded as two different heads must differ, or the bias is
    // being ignored or indexed at a fixed row - the failure that makes fifteen
    // of sixteen heads subtly wrong.
    let v = vectors();
    let p = params(&v, PleRowType::TrellisK6, TRELLIS_HEAD_DIM, true);
    let src = bytes(v["dequant"][3]["src"].as_str().expect("hex"));
    let mut head0 = vec![0f32; 160];
    let mut head9 = vec![0f32; 160];
    codec::dequant_row(&p, &src, 0, &mut head0).expect("decode");
    codec::dequant_row(&p, &src, 9, &mut head9).expect("decode");
    assert_ne!(head0, head9, "the bias table is per head");
}
